"""Package reviewable numeric evidence and the offline app, without media derivatives."""
import argparse,json,zipfile
from pathlib import Path
from urllib.parse import quote
from packages.config.loader import PROJECT_ROOT

HTML='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>见微 P0.3.3 · 真实素材验收</title><link rel="icon" href="data:,">
<style>:root{font-family:system-ui,-apple-system,sans-serif;color:#19352f;background:#f3f6f4}*{box-sizing:border-box}body{margin:0}main{max-width:1150px;margin:40px auto;padding:0 20px}h1{font-size:32px;margin-bottom:12px}p{line-height:1.7}a{color:#176d61}button,select{font:inherit;border:1px solid #bccdc6;background:white;border-radius:8px;padding:10px;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,section{background:white;border:1px solid #dce5df;border-radius:12px;padding:20px;margin:16px 0}.grid .card{margin:0}.number{display:block;font-size:28px;font-weight:650}small{color:#597268}.notice{background:#fff6dc;padding:14px;border-radius:10px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #e4e9e5;padding:11px 6px;white-space:nowrap}.scroll{overflow:auto}pre{white-space:pre-wrap;word-break:break-all;max-height:440px;overflow:auto;font-size:12px;background:#f5f7f5;padding:12px}.bar{position:relative;height:48px;background:#eef2ed;border-radius:8px;margin:15px 0}.bar button{position:absolute;height:100%;border:1px solid white;border-radius:2px;padding:0;opacity:.8}.bar button:hover{opacity:1;outline:2px solid #153e34}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}@media(max-width:650px){main{margin:22px auto;padding:0 14px}.grid{grid-template-columns:repeat(2,1fr)}h1{font-size:26px}section{padding:14px}}
</style><main><small>见微 / 主线 A / P0.3.3</small><h1>从真实素材，核对工程结果</h1><p>9 个原始录像分别提取冻结 R3D-18 特征，保持来源与视角隔离。这里展示已执行的数字报告；画面回查、文件接入和 SOP 人工审核使用完整本地 API 服务。</p><p class="notice">独立学习验收：blocked。当前录像均用于开发，机位、会话与稳定视角尚未核实。没有动作准确率或 SOP 合规率结论，尚未进入 P0.4。</p><div class="row"><a href="应用界面.html">打开应用离线演示</a><button id="download">下载完整数字报告</button></div><div class="grid" id="metrics"></div><section><h2>逐片接入与特征覆盖</h2><div class="scroll"><table><thead><tr><th>素材</th><th>有效片段</th><th>时间覆盖</th><th>匿名分段</th><th>可用因果对</th></tr></thead><tbody id="rows"></tbody></table></div><small>覆盖率按有效片段时间并集计算。片段固定 2 秒，步长 2 秒，16 帧；尾部不足一个片段不补造。</small></section><section><h2>匿名片段回查索引</h2><select id="source" aria-label="选择录像"></select><div class="bar" id="bar"></div><p id="detail"></p><p><a id="original" target="_blank" rel="noreferrer">查看仓库原片位置</a></p><small>点击色块查看代表片段时间。颜色仅表示本视频内匿名簇，不代表跨工位动作一致。原片需从 Git LFS 获取；此下载包不包含录像或截图。</small><details><summary>查看该来源版本与排除记录</summary><pre id="metadata"></pre></details></section><section><h2>SOP 候选目录</h2><p>26 个 PDF 页面，包含 3 页前置材料与 23 页正文；11 个编号章节与 7 个工位采用多对多候选映射。当前全部待工艺负责人核对。</p><div id="chapters"></div><p class="notice">规范期望、实际观测、预测、人工标注和语义候选分别保存。缺少仪器证据的扭矩、安规、电性能、老化保持 insufficient_evidence。批准映射不等于激活或视频真值。</p><details><summary>待核实事项</summary><pre id="warnings"></pre></details></section><p><a href="https://github.com/qoxgain/jianwei/tree/codex/p0-1-foundation">查看源代码与本地启动说明</a></p></main><script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),assets=data.acceptance.assets,colors=['#19766b','#5e8f79','#a2b86c','#6994a2'];const $=id=>document.getElementById(id);function element(tag,text){const e=document.createElement(tag);e.textContent=text;return e}
for(const [v,l]of[[assets.length,'原始录像'],[assets.reduce((s,a)=>s+a.eligible_rows,0),'有效特征片段'],[512,'冻结特征维度'],['未分配','全部数据分区']]){let c=element('div','');c.className='card';let n=element('span',v);n.className='number';c.append(n,element('small',l));$('metrics').append(c)}
for(const a of assets){let row=element('tr','');for(const v of [a.asset_id,a.eligible_rows,(100*a.coverage.fraction).toFixed(2)+'%',a.anonymous_segments,a.available_causal_pairs_metadata_only])row.append(element('td',v));$('rows').append(row);let o=element('option',a.asset_id);o.value=a.asset_id;$('source').append(o)}
function show(){const id=$('source').value,a=assets.find(v=>v.asset_id===id),report=data.explorations[id];$('bar').replaceChildren();const duration=report.coverage.source_domain_ms;for(const s of report.segments){let b=element('button','');b.style.left=(100*s.start_ms/duration)+'%';b.style.width=(100*(s.end_ms-s.start_ms)/duration)+'%';b.style.background=colors[Number(s.anonymous_cluster_id.split('_').pop())%colors.length];b.title=s.anonymous_cluster_id+' '+(s.start_ms/1000)+'–'+(s.end_ms/1000)+'秒';b.setAttribute('aria-label',b.title);b.onclick=()=>{$('detail').textContent=b.title+'；代表片段 '+(s.representative.start_ms/1000).toFixed(2)+'–'+(s.representative.end_ms/1000).toFixed(2)+' 秒。'};$('bar').append(b)}$('detail').textContent='选择色块，核对代表片段的原始时间。';$('metadata').textContent=JSON.stringify({source:a,discarded_clips:report.discarded_clips,rejected_rows:report.rejected_rows},null,2);$('original').href=data.source_links[id]}
$('source').onchange=show;show();for(const s of data.outline.sections){let p=element('p',s.document_id+' · '+s.title+' · PDF '+s.pdf_pages.join('、')+' 页');$('chapters').append(p)}$('warnings').textContent=JSON.stringify(data.outline.review_flags??data.outline.warnings??data.outline,null,2);$('download').onclick=()=>{let a=element('a','');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='P0.3.3-numeric-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
</script></html>'''


def build(source,output,app):
    acceptance=json.loads((source/'acceptance.json').read_text());assert len(acceptance['assets'])==9,'All nine real sources must finish before packaging'
    catalog=json.loads((PROJECT_ROOT/'datasets/video_samples/catalog.json').read_text())
    payload={'acceptance':acceptance,'explorations':{a['asset_id']:json.loads((source/a['asset_id']/'exploration.json').read_text()) for a in acceptance['assets']},'outline':json.loads((PROJECT_ROOT/'datasets/video_samples/bull_new_energy/sop/outline.draft.json').read_text()),'source_links':{a['asset_id']:'https://github.com/qoxgain/jianwei/blob/codex/p0-1-foundation/'+quote(a['path']) for a in catalog['assets'] if a['kind']=='video'}}
    encoded=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')
    html=HTML.replace('__DATA__',encoded)
    output.mkdir(parents=True,exist_ok=True)
    (output/'P0.3.3-验收Demo.html').write_text(html.replace('href="应用界面.html"', 'href="https://github.com/qoxgain/jianwei/raw/refs/heads/codex/p0-1-foundation/docs/demo/p0.3.3/jianwei-p0.3.3-demo.zip"').replace('打开应用离线演示', '下载应用离线演示'))
    with zipfile.ZipFile(output/'jianwei-p0.3.3-demo.zip','w',compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('index.html',html);archive.write(app,'应用界面.html')
        archive.writestr('README.txt','解压后打开 index.html 查看实际数字报告，打开 应用界面.html 查看离线应用。\n完整文件接入/原片回查/SOP复核需按 GitHub README 启动本地API。\n包内不含原始视频、PDF或衍生截图，不代表独立学习验收。\n')
    print(output/'jianwei-p0.3.3-demo.zip')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--source',type=Path,default=PROJECT_ROOT/'artifacts/p033');p.add_argument('--output',type=Path,default=PROJECT_ROOT/'docs/demo/p0.3.3');p.add_argument('--app',type=Path,default=PROJECT_ROOT/'apps/web/dist-demo/index.html');a=p.parse_args();build(a.source,a.output,a.app)
